mapper.select:
select node_id, topic_id, source_coord_sys, source_lng, source_lat, source_fingerprint,
       wgs84_lng, wgs84_lat, geo_status, dirty_reason, create_time, update_time
from orient_node_geo where node_id = #{nodeId}

mapper.update:
update orient_node_geo
set topic_id = #{topicId}, source_coord_sys = #{sourceCoordSys}, source_lng = #{sourceLng},
    source_lat = #{sourceLat}, source_fingerprint = #{sourceFingerprint}, wgs84_lng = #{wgs84Lng},
    wgs84_lat = #{wgs84Lat}, geo_status = #{geoStatus}, dirty_reason = #{dirtyReason},
    update_time = #{updateTime}
where node_id = #{nodeId}

update orient_task_alternative
set prompt_text = #{promptText}, answer_hash = #{answerHash}, enabled = #{enabled}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select count(1) from orient_task_attempt
where member_id = #{memberId} and activity_id = #{activityId} and topic_id = #{topicId}
  and play_instance_id = #{playInstanceId} and task_id = #{taskId}
  and alternative_task_type = 'PHOTO' and status = 0

mapper.update:
update orient_task_attempt
set status = #{toStatus}, review_by = #{reviewBy}, review_time = #{now}, update_time = #{now}
where id = #{id} and status = #{fromStatus}

mapper.select:
select id, member_id, activity_id, topic_id, play_instance_id, task_id, completed_via, source_attempt_id,
       completed_time
from orient_task_completion
where member_id = #{memberId} and activity_id = #{activityId} and topic_id = #{topicId}
  and play_instance_id = #{playInstanceId} and task_id = #{taskId}

select count(1) from player_node_progress
where member_id = #{memberId} and activity_id = #{activityId} and node_id = #{nodeId}
  and play_instance_id = #{playInstanceId}
  and status = 1 and del_flag = 0
  and topic_id = #{topicId}

select f.member_id as member_id, f.task_id as task_id, min(f.done_time) as done_time
from (
    select c.member_id, c.task_id, c.completed_time as done_time
    from orient_task_completion c
    where c.activity_id = #{activityId} and c.topic_id = #{topicId}
      and c.member_id in
      #{mid}
    union all
    select p.member_id, p.node_id as task_id, p.checkin_time as done_time
    from player_node_progress p
    where p.activity_id = #{activityId} and p.status = 1 and p.del_flag = 0
      and p.topic_id = #{topicId}
      and p.member_id in
      #{mid}
) f
group by f.member_id, f.task_id

select topic_id, insurance_required, night_start_minute, night_end_minute, weather_block, weather_reason,
       weather_block_until, update_by, create_time, update_time
from orient_safety_rule where topic_id = #{topicId}

mapper.update:
update orient_safety_rule
set insurance_required = 0, night_start_minute = #{nightStartMinute}, night_end_minute = #{nightEndMinute},
    weather_block = #{weatherBlock}, weather_reason = #{weatherReason},
    weather_block_until = #{weatherBlockUntil}, update_by = #{updateBy}, update_time = #{updateTime}
where topic_id = #{topicId}
